using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsBeamReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,Vector3 from,Vector3 at,string f){c.transform.position=from;c.transform.LookAt(at);var rt=new RenderTexture(1200,900,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1200,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1200,900),0,0);t.Apply();File.WriteAllBytes(f,t.EncodeToPNG());var pixels=t.GetPixels32();RenderTexture.active=old;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(t);return pixels;}
 public static void Run(){const string ev="Evidence/Target41Beam";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget41Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var c=UnityEngine.Object.FindAnyObjectByType<Camera>();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.65f;c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);
 var from=new Vector3(15,20,19);var at=new Vector3(0,3.5f,0);var pixels=Shot(c,from,at,ev+"/room.png");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget41Output/Structures/Ruins.prefab"));Check(pixels.SequenceEqual(Shot(c,from,at,ev+"/prefab.png")),"Prefab reload pixels");
 const string saved="Assets/RuinsTarget41Output/BeamPersistence.unity";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),saved);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene(saved);root=GameObject.Find("ruins_1").transform.parent.gameObject;c=UnityEngine.Object.FindAnyObjectByType<Camera>();sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);Check(pixels.SequenceEqual(Shot(c,from,at,ev+"/scene.png")),"Scene reload pixels");
 var old=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget36Output/Structures/Ruins.prefab"));int unchanged=0;foreach(Transform t in old.transform){if(!t.name.StartsWith("ruins_"))continue;var n=root.transform.Find(t.name);var a=t.GetComponent<MeshFilter>().sharedMesh;var b=n.GetComponent<MeshFilter>().sharedMesh;Check(a.vertices.SequenceEqual(b.vertices)&&a.normals.SequenceEqual(b.normals)&&a.uv.SequenceEqual(b.uv)&&a.triangles.SequenceEqual(b.triangles),"Old mesh "+t.name);Check(n.GetComponent<MeshCollider>().sharedMesh==b,"Collider identity");unchanged++;}Check(unchanged==43,"Old count");
 foreach(int id in new[]{44,45,46})root.transform.Find("ruins_"+id).gameObject.SetActive(false);root.SetActive(false);var prior=Shot(c,from,at,ev+"/unchanged-before.png");old.SetActive(false);root.SetActive(true);Check(prior.SequenceEqual(Shot(c,from,at,ev+"/unchanged-after.png")),"Other part pixels");UnityEngine.Object.DestroyImmediate(old);
 foreach(Transform t in root.transform)t.gameObject.SetActive(new[]{"ruins_44","ruins_45","ruins_46"}.Contains(t.name));var center=new Vector3(6.5f,4.8f,-7);c.orthographic=true;
 foreach(string view in new[]{"normal","close","opposite"}){sun.transform.rotation=view=="opposite"?Quaternion.Euler(27,130,0):Quaternion.Euler(38,-28,0);c.orthographicSize=view=="normal"?4.4f:2.6f;Shot(c,center+new Vector3(5,3.4f,7),center,ev+"/beam-"+view+".png");}
 var bm=root.transform.Find("ruins_46").GetComponent<MeshFilter>();var originalMesh=bm.sharedMesh;var plainMesh=UnityEngine.Object.Instantiate(originalMesh);var uv=plainMesh.uv;for(int i=0;i<uv.Length;i++)if(uv[i].x<-100){int type=(int)Math.Floor(uv[i].y/64);uv[i]=new Vector2(uv[i].x+128,uv[i].y-type*64-16);}plainMesh.uv=uv;bm.sharedMesh=plainMesh;sun.transform.rotation=Quaternion.Euler(38,-28,0);c.orthographicSize=2.6f;Shot(c,center+new Vector3(5,3.4f,7),center,ev+"/beam-plain.png");bm.sharedMesh=originalMesh;UnityEngine.Object.DestroyImmediate(plainMesh);
var baseline=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget39Output/Structures/Ruins.prefab"));foreach(Transform t in baseline.transform)t.gameObject.SetActive(new[]{"ruins_44","ruins_45","ruins_46"}.Contains(t.name));root.SetActive(false);sun.transform.rotation=Quaternion.Euler(38,-28,0);c.orthographicSize=2.6f;Shot(c,center+new Vector3(5,3.4f,7),center,ev+"/before-close.png");baseline.SetActive(false);root.SetActive(true);UnityEngine.Object.DestroyImmediate(baseline);
sun.transform.rotation=Quaternion.Euler(38,-28,0);c.orthographicSize=.85f;var end=new Vector3(8,6,-7);Shot(c,end+new Vector3(4,2,5),end,ev+"/beam-end.png");
 foreach(Transform t in root.transform)t.gameObject.SetActive(true);Physics.SyncTransforms();var beam=root.transform.Find("ruins_46").GetComponent<MeshCollider>();int contactRays=0;foreach(int id in new[]{44,45}){var col=root.transform.Find("ruins_"+id).GetComponent<MeshCollider>();float x=id==44?5:8;foreach(float dx in new[]{-.18f,0,.18f})foreach(float dz in new[]{-.18f,0,.18f}){var p=new Vector3(x+dx,6,-7+dz);RaycastHit a=default,b=default;Check(col.Raycast(new Ray(p+Vector3.up*.15f,Vector3.down),out a,.3f)&&beam.Raycast(new Ray(p-Vector3.up*.15f,Vector3.up),out b,.3f),"Bearing rays");Check(Math.Abs(a.point.y-6)<.001f&&Vector3.Distance(a.point,b.point)<.001f,"Bearing gap");contactRays+=2;}}
 var walker=new GameObject("BeamWalker");var cc=walker.AddComponent<CharacterController>();cc.height=1.6f;cc.center=new Vector3(0,.8f,0);cc.radius=.25f;cc.skinWidth=.015f;cc.stepOffset=.25f;walker.transform.position=new Vector3(6.5f,3.03f,-5.5f);Physics.SyncTransforms();for(int i=0;i<60;i++)cc.Move(new Vector3(0,-.025f,-.05f));Check(walker.transform.position.z<-8.4f&&Math.Abs(walker.transform.position.y-3)<.1f,"Under-beam passage");UnityEngine.Object.DestroyImmediate(walker);
 Check(beam.Raycast(new Ray(new Vector3(6.5f,5.8f,-7),Vector3.up),out var roof,1)&&Math.Abs(roof.point.y-6)<.001f,"Beam underside collider");
 var template=beam.gameObject;foreach(int n in new[]{9,225}){var clones=Enumerable.Range(0,n).Select(i=>{var o=UnityEngine.Object.Instantiate(template);o.transform.position=new Vector3(100+i*6,0,100);return o;}).ToArray();Check(clones.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared references");foreach(var o in clones)UnityEngine.Object.DestroyImmediate(o);}
 Check(!ShaderUtil.ShaderHasError(Shader.Find("MapRuins/AgedLimestone")),"Shader error");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"oldMeshes\":43,\"prefabScenePixelDelta\":0,\"otherPartsPixelDelta\":0,\"shared9And225\":true,\"bearingRays\":"+contactRays+",\"underBeamCapsuleWalk\":true,\"GPUmeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
